import { generateText } from "ai";
import type { Mission } from "./config";

/**
 * Bespoke missions for a custom zone, generated by an LLM.
 * Two paths, both resilient:
 *  - with real nearby places (OpenStreetMap / Overpass) -> place-specific missions pinned to those spots;
 *  - if Overpass is unreachable -> zone-themed missions that work anywhere in the area ("STREET").
 * On any failure returns null and the caller keeps the fixed generic missions.
 */

type Poi = { name: string; lat: number; lng: number; kind: string };

const OVERPASS_MIRRORS = [
  "https://overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
  "https://overpass.private.coffee/api/interpreter",
  "https://maps.mail.ru/osm/tools/overpass/api/interpreter",
];

/** POST an Overpass query to the first mirror that answers with JSON. */
async function overpass(query: string): Promise<{ elements?: { tags?: Record<string, string>; lat?: number; lon?: number; center?: { lat: number; lon: number } }[] } | null> {
  for (const url of OVERPASS_MIRRORS) {
    try {
      const resp = await fetch(url, {
        method: "POST",
        headers: {
          "content-type": "application/x-www-form-urlencoded",
          accept: "application/json",
          "user-agent": "NightHunt/1.0 (hide-and-seek party game; missions)",
        },
        body: "data=" + encodeURIComponent(query),
        signal: AbortSignal.timeout(15_000),
      });
      if (!resp.ok) continue;
      const txt = await resp.text();
      if (!txt.trim().startsWith("{")) continue;
      return JSON.parse(txt);
    } catch {
      // try the next mirror
    }
  }
  return null;
}

/** Notable, nameable places inside the play area. Empty if Overpass is unreachable. */
async function fetchPois(lat: number, lng: number, radiusM: number): Promise<Poi[]> {
  const r = Math.max(120, Math.min(3000, Math.round(radiusM)));
  const q = `[out:json][timeout:15];(
    node(around:${r},${lat},${lng})["name"]["tourism"];
    node(around:${r},${lat},${lng})["name"]["historic"];
    way(around:${r},${lat},${lng})["name"]["historic"];
    way(around:${r},${lat},${lng})["name"]["leisure"~"park|garden|playground|pitch"];
    node(around:${r},${lat},${lng})["name"]["amenity"~"place_of_worship|theatre|cinema|fountain|library|townhall"];
    way(around:${r},${lat},${lng})["name"]["amenity"~"marketplace"];
    node(around:${r},${lat},${lng})["name"]["natural"~"peak|spring|tree"];
  );out center 80;`;
  const data = await overpass(q);
  if (!data) return [];
  const seen = new Set<string>();
  const out: Poi[] = [];
  for (const el of data.elements ?? []) {
    const name = el.tags?.name?.trim();
    if (!name || seen.has(name.toLowerCase())) continue;
    const plat = el.lat ?? el.center?.lat;
    const plng = el.lon ?? el.center?.lon;
    if (plat == null || plng == null) continue;
    seen.add(name.toLowerCase());
    const t = el.tags!;
    out.push({ name, lat: plat, lng: plng, kind: t.tourism || t.historic || t.leisure || t.amenity || t.natural || "luogo" });
    if (out.length >= 40) break;
  }
  return out;
}

/** Pulls the first JSON array out of a model reply, tolerating code fences and chatter. */
function extractJsonArray(text: string): unknown[] | null {
  const start = text.indexOf("[");
  const end = text.lastIndexOf("]");
  if (start < 0 || end <= start) return null;
  try {
    const v = JSON.parse(text.slice(start, end + 1));
    return Array.isArray(v) ? v : null;
  } catch {
    return null;
  }
}

/** The configured model: Groq (free) if its key is set, otherwise the Vercel AI Gateway (OIDC in prod). */
async function pickModel(): Promise<Parameters<typeof generateText>[0]["model"]> {
  if (process.env.GROQ_API_KEY) {
    const { createGroq } = await import("@ai-sdk/groq");
    const groq = createGroq({ apiKey: process.env.GROQ_API_KEY });
    return groq(process.env.MISSIONS_AI_MODEL || "llama-3.3-70b-versatile");
  }
  return process.env.MISSIONS_AI_MODEL || "anthropic/claude-haiku-4.5";
}

const SAFETY = `REGOLE DI SICUREZZA obbligatorie: tutto da spazi pubblici e da fuori; mai entrare in proprietà privata o recintata; mai spaventare o disturbare passanti o chi dorme; niente di pericoloso o illegale.`;

/**
 * Returns a bespoke mission set for the zone, or null to fall back to the fixed generic one.
 */
export async function generateMissions(zoneName: string, lat: number, lng: number, radiusM: number): Promise<Mission[] | null> {
  try {
    const model = await pickModel();
    const pois = await fetchPois(lat, lng, radiusM);

    if (pois.length >= 4) {
      // Place-specific missions pinned to the real spots.
      const picked = pois.slice(0, 24);
      const list = picked.map((p, i) => `${i + 1}. ${p.name} (${p.kind})`).join("\n");
      const prompt = `Sei il game designer di "Night Hunt", un nascondino horror-comico che si gioca di sera per le strade di un quartiere.
Zona di gioco: "${zoneName}". Luoghi REALI dentro l'area (numerati):
${list}

Scrivi da 10 a 14 missioni, UNA per luogo diverso, scegliendo i più evocativi.
Tono: horror ironico e teatrale, da Halloween. In ITALIANO.
Ogni missione è una foto o un breve video (max 20s) che due amici si fanno a vicenda in quel punto.
${SAFETY}

Rispondi SOLO con un array JSON, niente testo attorno. Ogni elemento:
{"poi": <numero del luogo>, "title": "<titolo breve>", "task": "<istruzioni, 1-2 frasi>", "kind": "PHOTO"|"VIDEO", "points": <intero 300-900>}`;
      const { text } = await generateText({ model, prompt, temperature: 0.9, maxOutputTokens: 2500 });
      const arr = extractJsonArray(text);
      if (!arr) return null;
      const missions: Mission[] = [];
      for (const raw of arr) {
        const m = raw as { poi?: number; title?: string; task?: string; kind?: string; points?: number };
        const poi = picked[Number(m.poi) - 1];
        const title = String(m.title ?? "").trim();
        const task = String(m.task ?? "").trim();
        if (!poi || title.length < 2 || task.length < 8) continue;
        missions.push({
          id: `ai-${missions.length + 1}`, title: title.slice(0, 80), place: poi.name.slice(0, 80),
          lat: poi.lat, lng: poi.lng, radiusM: 45, kind: m.kind === "VIDEO" ? "VIDEO" : "PHOTO",
          task: task.slice(0, 400), points: Math.max(300, Math.min(900, Math.round(Number(m.points) || 500))),
        });
        if (missions.length >= 14) break;
      }
      return missions.length >= 6 ? missions : null;
    }

    // No reliable place list: zone-themed missions playable anywhere in the area.
    const prompt = `Sei il game designer di "Night Hunt", un nascondino horror-comico che si gioca di sera per le strade.
Zona di gioco: "${zoneName}" (gioca un gruppo di amici dentro quest'area).
Scrivi da 10 a 12 missioni a tema, da fare in QUALSIASI punto della zona (non legate a un luogo preciso): panchine, vetrine, vicoli, lampioni, citofoni, cartelli, androni, ecc.
Tono: horror ironico e teatrale, da Halloween. In ITALIANO.
Ogni missione è una foto o un breve video (max 20s) che due amici si fanno a vicenda.
${SAFETY}

Rispondi SOLO con un array JSON, niente testo attorno. Ogni elemento:
{"title": "<titolo breve>", "task": "<istruzioni, 1-2 frasi>", "kind": "PHOTO"|"VIDEO", "points": <intero 300-900>}`;
    const { text } = await generateText({ model, prompt, temperature: 0.95, maxOutputTokens: 2200 });
    const arr = extractJsonArray(text);
    if (!arr) return null;
    const missions: Mission[] = [];
    for (const raw of arr) {
      const m = raw as { title?: string; task?: string; kind?: string; points?: number };
      const title = String(m.title ?? "").trim();
      const task = String(m.task ?? "").trim();
      if (title.length < 2 || task.length < 8) continue;
      missions.push({
        id: `ai-${missions.length + 1}`, special: "STREET", title: title.slice(0, 80), place: "Ovunque nella zona",
        lat: 0, lng: 0, radiusM: 0, kind: m.kind === "VIDEO" ? "VIDEO" : "PHOTO",
        task: task.slice(0, 400), points: Math.max(300, Math.min(900, Math.round(Number(m.points) || 500))),
      });
      if (missions.length >= 12) break;
    }
    return missions.length >= 6 ? missions : null;
  } catch (e) {
    console.warn("generateMissions:", (e as Error).message);
    return null;
  }
}
